1	package cli
2	
3	import (
4		"fmt"
5		"os"
6		"sort"
7		"strings"
8	)
9	
10	// retrieve.go is the unified retrieval layer behind the qmd-inspired verbs
11	// (search/vsearch/query). It ranks across the brain's text layers — facts,
12	// history, docs — and merges the per-source ranked lists with RRF. Each layer
13	// keeps its own best ranker; RRF fuses them by rank so their incomparable raw
14	// scores don't fight.
15	
16	type unifiedResult struct {
17		Source  string  `json:"source"` // fact | history | doc
18		ID      string  `json:"id"`     // prefixed, addressable by get/multi-get
19		Path    string  `json:"path,omitempty"`
20		Heading string  `json:"heading,omitempty"`
21		Line    int     `json:"line,omitempty"`
22		Text    string  `json:"text"`
23		Score   float64 `json:"score,omitempty"` // omitted for unranked results (get/multi-get); RRF scores are always > 0
24	}
25	
26	type retrievalMode int
27	
28	const (
29		modeLexical retrievalMode = iota // search
30		modeVector                       // vsearch
31		modeHybrid                       // query
32	)
33	
34	func embedQueryWith(e Embedder, q string) []float32 {
35		if qe, ok := e.(queryEmbedder); ok {
36			return qe.EmbedQuery(q)
37		}
38		return e.Embed(q)
39	}
40	
41	// retrieveUnified ranks across facts + history + docs. Lexical (search) and
42	// hybrid (query) include all three; vector (vsearch) covers facts + docs —
43	// history vectors are Model2Vec noise and embedding tens of thousands of records
44	// per query is too slow, so they join the vector arm once Stage 1b's embedder
45	// lands. Missing layers are skipped, not errors.
46	func retrieveUnified(brainDir, branch, query string, limit int, mode retrievalMode) ([]unifiedResult, error) {
47		if limit <= 0 {
48			limit = 10
49		}
50		// loadFacts surfaces corrupt NDJSON as a hard error; propagate it rather than
51		// presenting a broken store as "no results".
52		all, err := loadFacts(brainDir, branch)
53		if err != nil {
54			return nil, err
55		}
56		active := make([]factRecord, 0, len(all))
57		for _, f := range all {
58			if f.Status == factStatusActive {
59				active = append(active, f)
60			}
61		}
62		var e Embedder
63		if mode != modeLexical {
64			e = defaultEmbedder()
65		}
66	
67		var lists [][]unifiedResult
68	
69		// Facts.
70		if len(active) > 0 {
71			switch mode {
72			case modeLexical:
73				lists = append(lists, factsToUnified(rankFacts(active, query, limit*2, false)))
74			case modeVector:
75				if e != nil {
76					// Pass the full set: factsVectorRanked ranks active facts but caches
77					// (and prunes) every present fact, matching the reranker's shared store.
78					lists = append(lists, factsToUnified(factsVectorRanked(brainDir, branch, all, query, e, limit*2)))
79				}
80			case modeHybrid:
81				var rr *semanticReranker
82				if e != nil {
83					rr = newSemanticRerankerForBranch(e, brainDir, branch)
84				}
85				lists = append(lists, factsToUnified(rankFactsFused(active, query, limit*2, false, rr)))
86				if rr != nil {
87					rr.retain(all) // keep every present fact's vector; prune only departed facts (matches recall/brief)
88					_ = rr.flush()
89				}
90			}
91		}
92	
93		// History — BM25 (lexical / hybrid only). The FTS index is an optimization,
94		// never load-bearing (see history_fts.go): on a build/open/query failure fall
95		// back to the in-memory substring scorer. But a corrupt manifest, or a history
96		// index the manifest declares yet is missing/unreadable, is a real storage
97		// problem — surface it rather than returning silently-incomplete results. A
98		// brain with no history source (nil) is legitimately skipped.
99		if mode != modeVector {
100			manifest, err := loadBrainManifest(brainDir)
101			if err != nil {
102				return nil, err
103			}
104			if manifest.Sources != nil && manifest.Sources.History != nil {
105				index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
106				if err != nil {
107					return nil, fmt.Errorf("load history index: %w", err)
108				}
109				scored, ok := rankHistoryViaFTS(brainDir, index, "history", query, limit*2)
110				if !ok {
111					scored = rankHistoryRecordsScored(index, "history", query, limit*2, 0)
112				}
113				if len(scored) > 0 {
114					lists = append(lists, historyToUnified(scored))
115				}
116			}
117		}
118	
119		// Docs — lexical (search/query) and/or vector (vsearch/query). In hybrid mode
120		// docs join BOTH arms, mirroring facts. A never-built doc index is skipped; a
121		// corrupt/unreadable one is a real storage problem and is surfaced.
122		docIdx, derr := loadDocIndex(brainDir)
123		switch {
124		case derr == nil && len(docIdx.Records) > 0:
125			if mode != modeVector {
126				// FTS is an optimization, never load-bearing: fall back to the in-memory
127				// lexical scorer so docs don't vanish when the doc FTS index can't open.
128				scored, ok := rankDocsViaFTS(brainDir, docIdx, query, limit*2)
129				if !ok {
130					scored = rankDocsLexical(docIdx, query, limit*2)
131				}
132				if len(scored) > 0 {
133					lists = append(lists, docsToUnified(scored))
134				}
135			}
136			if mode != modeLexical && e != nil {
137				lists = append(lists, docsVectorRanked(brainDir, docIdx, query, e, limit*2))
138			}
139		case derr != nil && !os.IsNotExist(derr):
140			return nil, fmt.Errorf("load doc index: %w", derr)
141		}
142	
143		return rrfMergeUnified(lists, limit), nil
144	}
145	
146	// factsVectorRanked ranks active facts by cosine. facts is the full present set
147	// (all statuses): active facts are ranked, but every present fact is embedded and
148	// retained in the shared cache so this path keeps the same vectors the recall/brief
149	// reranker does — and departed facts are pruned so the on-disk cache stays bounded.
150	func factsVectorRanked(brainDir, branch string, facts []factRecord, query string, e Embedder, limit int) []factRecord {
151		// An empty query vector means the embedder is unavailable (e.g. Ollama down).
152		// Return no semantic results rather than an arbitrary top-N: every cosine
153		// would be 0 and the sort would just echo input order.
154		qv := embedQueryWith(e, query)
155		if len(qv) == 0 {
156			return nil
157		}
158		store := newEmbedStore(brainDir, branch, e.ID(), e.Dim())
159		cache := store.load()
160		dirty := false
161		present := make(map[string]struct{}, len(facts))
162		type sc struct {
163			rec factRecord
164			cos float64
165		}
166		scored := make([]sc, 0, len(facts))
167		for _, f := range facts {
168			present[f.ID] = struct{}{}
169			v, ok := cache[f.ID]
170			if !ok {
171				v = e.Embed(f.Text)
172				if len(v) == len(qv) {
173					cache[f.ID] = v // never cache empty/mismatched vectors
174					dirty = true
175				}
176			}
177			if f.Status != factStatusActive || len(v) != len(qv) {
178				continue // rank active facts only; skip degenerate vectors
179			}
180			scored = append(scored, sc{f, cosineFloat32(qv, v)})
181		}
182		if saved := pruneToPresent(cache, present); dirty || saved {
183			_ = store.savePresent(cache, present)
184		}
185		sort.Slice(scored, func(a, b int) bool { return scored[a].cos > scored[b].cos })
186		out := make([]factRecord, 0, min(limit, len(scored)))
187		for _, s := range scored {
188			out = append(out, s.rec)
189			if len(out) >= limit {
190				break
191			}
192		}
193		return out
194	}
195	
196	// pruneToPresent drops cache entries whose id is no longer in present, keeping the
197	// on-disk vector cache bounded to the current corpus. Reports whether it removed
198	// anything (so callers save even when no new vector was embedded).
199	func pruneToPresent(cache map[string][]float32, present map[string]struct{}) bool {
200		removed := false
201		for id := range cache {
202			if _, ok := present[id]; !ok {
203				delete(cache, id)
204				removed = true
205			}
206		}
207		return removed
208	}
209	
210	func docsVectorRanked(brainDir string, index docIndex, query string, e Embedder, limit int) []unifiedResult {
211		// Same guard as factsVectorRanked: no query vector → no doc semantic hits,
212		// not arbitrary docs ranked by all-zero cosines.
213		qv := embedQueryWith(e, query)
214		if len(qv) == 0 {
215			return nil
216		}
217		store := newDocEmbedStore(brainDir, e.ID(), e.Dim())
218		cache := store.load()
219		dirty := false
220		present := make(map[string]struct{}, len(index.Records))
221		type sc struct {
222			i   int
223			cos float64
224		}
225		scored := make([]sc, 0, len(index.Records))
226		for i, r := range index.Records {
227			present[r.ID] = struct{}{}
228			v, ok := cache[r.ID]
229			if !ok {
230				v = e.Embed(r.Text)
231				if len(v) == len(qv) {
232					cache[r.ID] = v
233					dirty = true
234				}
235			}
236			if len(v) != len(qv) {
237				continue
238			}
239			scored = append(scored, sc{i, cosineFloat32(qv, v)})
240		}
241		// Doc ids are content-derived, so any rebuild churns them; prune departed ids
242		// so the cache stays bounded to the current doc corpus.
243		if saved := pruneToPresent(cache, present); dirty || saved {
244			_ = store.savePresent(cache, present)
245		}
246		sort.Slice(scored, func(a, b int) bool { return scored[a].cos > scored[b].cos })
247		out := make([]unifiedResult, 0, min(limit, len(scored)))
248		for _, s := range scored {
249			out = append(out, docToUnified(index.Records[s.i]))
250			if len(out) >= limit {
251				break
252			}
253		}
254		return out
255	}
256	
257	func factsToUnified(facts []factRecord) []unifiedResult {
258		// fact ids are already prefixed "fact:" (factRecordID); history likewise.
259		out := make([]unifiedResult, len(facts))
260		for i, f := range facts {
261			out[i] = unifiedResult{Source: "fact", ID: f.ID, Path: strings.Join(f.Paths, ","), Text: f.Text}
262		}
263		return out
264	}
265	
266	func historyToUnified(scored []scoredHistoryRecord) []unifiedResult {
267		out := make([]unifiedResult, len(scored))
268		for i, s := range scored {
269			out[i] = unifiedResult{Source: "history", ID: s.Record.ID, Path: s.Record.Path, Line: s.Record.Line, Heading: s.Record.Kind, Text: s.Record.Summary}
270		}
271		return out
272	}
273	
274	func docToUnified(r docRecord) unifiedResult {
275		return unifiedResult{Source: "doc", ID: "doc:" + r.ID, Path: r.Path, Line: r.Line, Heading: r.Heading, Text: r.Text}
276	}
277	
278	func docsToUnified(scored []scoredDocRecord) []unifiedResult {
279		out := make([]unifiedResult, len(scored))
280		for i, s := range scored {
281			out[i] = docToUnified(s.Record)
282		}
283		return out
284	}
285	
286	func rrfMergeUnified(lists [][]unifiedResult, limit int) []unifiedResult {
287		fused := map[string]float64{}
288		rec := map[string]unifiedResult{}
289		for _, list := range lists {
290			for rank, r := range list {
291				fused[r.ID] += 1.0 / (rrfK + float64(rank+1))
292				if _, ok := rec[r.ID]; !ok {
293					rec[r.ID] = r
294				}
295			}
296		}
297		out := make([]unifiedResult, 0, len(rec))
298		for id, r := range rec {
299			r.Score = fused[id]
300			out = append(out, r)
301		}
302		sort.Slice(out, func(a, b int) bool {
303			if out[a].Score != out[b].Score {
304				return out[a].Score > out[b].Score
305			}
306			return out[a].ID < out[b].ID
307		})
308		if len(out) > limit {
309			out = out[:limit]
310		}
311		return out
312	}
313	
314	// getUnifiedBatch resolves prefixed ids (fact:/history:/doc:) to full records,
315	// loading each corpus at most once and indexing it by id. get/multi-get (and the
316	// MCP brain_get/brain_multi_get) route through here so resolving N ids is O(corpus
317	// + N), not O(N × corpus) — the latter rescans the full history per id and is
318	// pathological on large brains. Results preserve input order.
319	func getUnifiedBatch(brainDir, branch string, ids []string) (found []unifiedResult, missing []string, err error) {
320		var wantFact, wantHistory, wantDoc bool
321		for _, id := range ids {
322			switch {
323			case strings.HasPrefix(id, "fact:"):
324				wantFact = true
325			case strings.HasPrefix(id, "history:"):
326				wantHistory = true
327			case strings.HasPrefix(id, "doc:"):
328				wantDoc = true
329			}
330		}
331		factByID := map[string]factRecord{}
332		if wantFact {
333			// Surface a corrupt facts store as an error, not a misleading "not found".
334			facts, ferr := loadFacts(brainDir, branch)
335			if ferr != nil {
336				return nil, nil, ferr
337			}
338			for _, f := range facts {
339				factByID[f.ID] = f
340			}
341		}
342		histByID := map[string]historyRecord{}
343		if wantHistory {
344			// A corrupt manifest, or a history index the manifest declares but that is
345			// missing/unreadable, is a real storage problem — surface it rather than
346			// reporting every history:* id as "not found". A brain with no history source
347			// (nil) legitimately has no such records, so leave histByID empty.
348			manifest, err := loadBrainManifest(brainDir)
349			if err != nil {
350				return nil, nil, err
351			}
352			if manifest.Sources != nil && manifest.Sources.History != nil {
353				index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
354				if err != nil {
355					return nil, nil, fmt.Errorf("load history index: %w", err)
356				}
357				for _, r := range index.Records {
358					histByID[r.ID] = r
359				}
360			}
361		}
362		docByID := map[string]docRecord{}
363		if wantDoc {
364			// A never-built doc index is not an error (doc:* ids just report "not
365			// found"); a corrupt/unreadable one is — surface it.
366			index, err := loadDocIndex(brainDir)
367			switch {
368			case err == nil:
369				for _, r := range index.Records {
370					docByID[r.ID] = r
371				}
372			case !os.IsNotExist(err):
373				return nil, nil, fmt.Errorf("load doc index: %w", err)
374			}
375		}
376		for _, id := range ids {
377			switch {
378			case strings.HasPrefix(id, "fact:"):
379				if f, ok := factByID[id]; ok {
380					found = append(found, factsToUnified([]factRecord{f})[0])
381					continue
382				}
383			case strings.HasPrefix(id, "history:"):
384				if r, ok := histByID[id]; ok {
385					found = append(found, historyToUnified([]scoredHistoryRecord{{Record: r}})[0])
386					continue
387				}
388			case strings.HasPrefix(id, "doc:"):
389				if r, ok := docByID[strings.TrimPrefix(id, "doc:")]; ok {
390					found = append(found, docToUnified(r))
391					continue
392				}
393			}
394			missing = append(missing, id)
395		}
396		return found, missing, nil
397	}
