47	func newMCPCommand(opts Options) *cobra.Command {
48		return &cobra.Command{
49			Use:   "mcp",
50			Short: "Serve local brain tools over MCP stdio",
51			Args:  cobra.NoArgs,
52			RunE: func(cmd *cobra.Command, args []string) error {
53				return runMCP(cmd.Context(), cmd.InOrStdin(), cmd.OutOrStdout(), opts)
54			},
55		}
