58	func runMCP(ctx context.Context, in io.Reader, out io.Writer, opts Options) error {
59		reader := bufio.NewReader(in)
60		debugLog := os.Getenv("ENTIRE_BRAIN_MCP_DEBUG_LOG")
61		mcpDebugLog(debugLog, "start")
62		for {
63			msg, frameMode, err := readMCPMessage(reader)
64			if errors.Is(err, io.EOF) {
65				mcpDebugLog(debugLog, "eof")
66				return nil
67			}
68			if errors.Is(err, errMCPRecoverable) {
69				// Reply with a JSON-RPC parse error and keep serving; one bad frame
70				// must not kill the whole MCP session.
71				mcpDebugLog(debugLog, "parse_error: "+err.Error())
72				resp := mcpMessage{JSONRPC: "2.0", Error: &mcpError{Code: -32700, Message: "parse error"}}
73				if werr := writeMCPMessage(out, resp, frameMode); werr != nil {
74					mcpDebugLog(debugLog, "write_error: "+werr.Error())
75					return werr
76				}
77				continue
78			}
79			if err != nil {
80				mcpDebugLog(debugLog, "read_error: "+err.Error())
81				return err
82			}
83			mcpDebugLog(debugLog, "message: "+msg.Method)
84			if msg.ID == nil {
85				continue
86			}
87			response := handleMCPMessage(ctx, opts, msg)
88			if err := writeMCPMessage(out, response, frameMode); err != nil {
89				mcpDebugLog(debugLog, "write_error: "+err.Error())
90				return err
91			}
92			mcpDebugLog(debugLog, "response: "+msg.Method)
93			mcpDebugLogToolResult(debugLog, msg, response)
94		}
95	}
