97	func mcpDebugLog(path, line string) {
98		if strings.TrimSpace(path) == "" {
99			return
100		}
101		f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
102		if err != nil {
103			return
104		}
105		defer f.Close()
106		fmt.Fprintln(f, line)
