114	func mcpDebugToolCall(raw json.RawMessage) mcpDebugToolCallInfo {
115		var params struct {
116			Name      string         `json:"name"`
117			Arguments map[string]any `json:"arguments"`
118		}
119		if err := json.Unmarshal(raw, &params); err != nil {
120			return mcpDebugToolCallInfo{}
121		}
122		name := strings.TrimSpace(params.Name)
123		if name == "" {
124			return mcpDebugToolCallInfo{}
125		}
126		name = strings.Map(func(r rune) rune {
127			if r < 32 || r == 127 {
128				return -1
129			}
130			return r
131		}, name)
132		safe := make(map[string]any)
133		for _, key := range []string{"blind_spots", "include_deletions", "location_only"} {
134			if value, ok := params.Arguments[key].(bool); ok {
135				safe[key] = value
136			}
137		}
138		if name == "brain_workspace_regressions" || name == "brain_workspace_review" {
139			if value, ok := params.Arguments["workspace"].(string); ok {
140				workspace := strings.TrimSpace(value)
141				if validateWorkspaceName(workspace) == nil {
142					safe["workspace"] = workspace
143				}
144			}
145		}
146		return mcpDebugToolCallInfo{name: name, safeArgs: safe}
147	}
