174	func handleMCPMessage(ctx context.Context, opts Options, msg mcpMessage) mcpMessage {
175		response := mcpMessage{JSONRPC: "2.0", ID: msg.ID}
176		switch msg.Method {
177		case "initialize":
178			protocolVersion := mcpInitializeProtocolVersion(msg.Params)
179			response.Result = map[string]any{
180				"protocolVersion": protocolVersion,
181				"capabilities":    map[string]any{"tools": map[string]any{}},
182				"serverInfo":      map[string]any{"name": "entire-brain", "version": opts.Version},
183			}
184		case "tools/list":
185			response.Result = map[string]any{"tools": mcpToolDefinitions()}
186		case "tools/call":
187			result, err := handleMCPToolCall(ctx, opts, msg.Params)
188			if err != nil {
189				response.Error = &mcpError{Code: -32000, Message: err.Error()}
190			} else {
191				response.Result = result
192			}
193		default:
194			response.Error = &mcpError{Code: -32601, Message: "method not found"}
195		}
196		return response
197	}
