305				"description": "Flag suspected regressions: lines the session history asserts but the current tree changed (default) or, with include_deletions, deleted (file:line, expected value, confidence, provenance).",
306				"inputSchema": objectSchema([]string{"query"}, map[string]any{"query": stringArg("query", "Task description plus the failing symbols/identifiers"), "limit": integerArg("limit", "Maximum suspected regressions"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (higher recall, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
307			},
308			{
309				"name":        "brain_review",
310				"description": "Diff-less review (versioned schema_version contract): review the current working tree against the brain's memory (no branch-vs-base diff) and return severity-ranked suspected-regression findings with provenance. The contract `entire review`'s diff-less mode and `labs investigate` are intended to bind to; those consumers are cross-repo (entireio/cli) and not yet landed. See docs/diffless_review_seam.md.",
311				"inputSchema": objectSchema([]string{"query"}, map[string]any{"query": stringArg("query", "What to review plus the relevant symbols/identifiers"), "limit": integerArg("limit", "Maximum findings"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (lower confidence, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
312			},
313			{
314				"name":        "brain_workspace_regressions",
315				"description": "Flag suspected regressions across every repo in a local multi-repo workspace (each brain's memory vs that repo's current tree). Tolerates sessions-only brains; results are aggregated by repo_key.",
316				"inputSchema": objectSchema([]string{"workspace", "query"}, map[string]any{"workspace": stringArg("workspace", "Workspace name"), "query": stringArg("query", "Task description plus the failing symbols/identifiers"), "limit": integerArg("limit", "Maximum suspected regressions per repo"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (higher recall, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
317			},
318			{
319				"name":        "brain_workspace_review",
320				"description": "Cross-repo diff-less review: review each repo's current tree in a local workspace against its brain's memory and return severity-ranked suspected-regression findings per repo. The multi-brain extension of the same versioned contract; consumers are cross-repo (entireio/cli) and not yet landed. See docs/diffless_review_seam.md.",
321				"inputSchema": objectSchema([]string{"workspace", "query"}, map[string]any{"workspace": stringArg("workspace", "Workspace name"), "query": stringArg("query", "What to review plus the relevant symbols/identifiers"), "limit": integerArg("limit", "Maximum findings per repo"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (lower confidence, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
322			},
323		}
324	}
325	
326	func handleMCPToolCall(ctx context.Context, opts Options, raw json.RawMessage) (map[string]any, error) {
327		var params mcpToolCallParams
328		if err := json.Unmarshal(raw, &params); err != nil {
329			return nil, err
330		}
331		if err := validateMCPToolArguments(params.Name, params.Arguments); err != nil {
332			return nil, err
333		}
334		var out bytes.Buffer
335		cmd := &cobra.Command{Use: params.Name}
336		cmd.SetOut(&out)
337		cmd.SetErr(io.Discard)
338		cmd.SetContext(ctx)
339		limit, err := mcpPositiveInt(params.Arguments, "limit", 20)
340		if err != nil {
341			return nil, err
342		}
343		query, err := mcpOptionalString(params.Arguments, "query")
344		if err != nil {
345			return nil, err
346		}
347		branch, err := mcpOptionalString(params.Arguments, "branch")
348		if err != nil {
349			return nil, err
350		}
351		switch params.Name {
352		case "brain_stale":
353			target := "."
354			if opts.Env.RepoRoot != "" {
355				target = opts.Env.RepoRoot
356			}
357			var blindSpots bool
358			blindSpots, err = mcpBool(params.Arguments, "blind_spots")
359			if err == nil {
360				err = runSemanticStale(ctx, cmd, opts, target, true, blindSpots)
361			}
362		case "brain_brief":
363			task, stringErr := mcpOptionalString(params.Arguments, "task")
364			if stringErr != nil {
365				err = stringErr
366				break
367			}
368			if strings.TrimSpace(task) == "" {
369				err = errors.New("task is required")
370			} else {
371				err = runBrainBrief(ctx, cmd, opts, brainBriefOptions{limit: limit, json: true}, task)
372			}
373		case "brain_query":
374			err = requireMCPQuery(query)
375			if err == nil {
376				err = runRetrieve(ctx, cmd, opts, query, modeHybrid, limit, branch, true)
377			}
378		case "brain_search":
379			err = requireMCPQuery(query)
380			if err == nil {
381				err = runRetrieve(ctx, cmd, opts, query, modeLexical, limit, branch, true)
382			}
383		case "brain_vsearch":
384			err = requireMCPQuery(query)
385			if err == nil {
386				err = runRetrieve(ctx, cmd, opts, query, modeVector, limit, branch, true)
387			}
388		case "brain_get":
389			id, stringErr := mcpOptionalString(params.Arguments, "id")
390			if stringErr != nil {
391				err = stringErr
392				break
393			}
394			id = strings.TrimSpace(id)
395			if id == "" {
396				err = errors.New("id is required")
397			} else {
398				err = runGet(ctx, cmd, opts, []string{id}, branch, true)
399			}
400		case "brain_multi_get":
401			ids, sliceErr := mcpStringSlice(params.Arguments, "ids")
402			if sliceErr != nil {
403				err = sliceErr
404				break
405			}
406			if len(ids) == 0 {
407				err = errors.New("ids is required")
408			} else {
409				err = runGet(ctx, cmd, opts, ids, branch, true)
410			}
411		case "brain_context":
412			err = requireMCPQuery(query)
413			if err == nil {
414				err = runSemanticContext(ctx, cmd, opts, semanticContextOptions{limit: limit, json: true}, query)
415			}
416		case "brain_impact":
417			err = requireMCPQuery(query)
418			if err == nil {
419				depth, depthErr := mcpPositiveInt(params.Arguments, "depth", 1)
420				if depthErr != nil {
421					err = depthErr
422				} else {
423					err = runSemanticImpact(ctx, cmd, opts, semanticImpactOptions{limit: limit, depth: depth, json: true}, query)
424				}
425			}
426		case "brain_changes":
427			err = runSemanticChanges(ctx, cmd, opts, semanticChangesOptions{limit: limit, json: true})
428		case "brain_code":
429			err = requireMCPQuery(query)
430			if err == nil {
431				err = runSemanticQuery(ctx, cmd, opts, semanticQueryOptions{limit: limit, json: true}, query)
432			}
433		case "brain_tests":
434			err = requireMCPQuery(query)
435			if err == nil {
436				err = runSemanticTests(ctx, cmd, opts, semanticTestsOptions{limit: limit, json: true}, query)
437			}
438		case "brain_boundaries":
439			kind, stringErr := mcpOptionalString(params.Arguments, "kind")
440			if stringErr != nil {
441				err = stringErr
442				break
443			}
444			kind = strings.TrimSpace(kind)
445			if kind == "" {
446				kind = "tool"
447			}
448			spec, specErr := inspectBoundarySpec(kind)
449			if specErr != nil {
450				err = specErr
451			} else {
452				err = runSemanticBoundary(ctx, cmd, opts, semanticBoundaryOptions{limit: limit, json: true}, spec)
453			}
454		case "brain_regressions":
455			err = requireMCPQuery(query)
456			if err == nil {
457				inc, loc, boolErr := mcpRegressionBooleans(params.Arguments)
458				if boolErr != nil {
459					err = boolErr
460					break
461				}
462				err = runRegressionDetect(ctx, cmd, opts, regressionDetectorOptions{limit: limit, json: true, includeDeletions: inc, locationOnly: loc}, query)
463			}
464		case "brain_review":
465			err = requireMCPQuery(query)
466			if err == nil {
467				inc, loc, boolErr := mcpRegressionBooleans(params.Arguments)
468				if boolErr != nil {
469					err = boolErr
470					break
471				}
472				err = runBrainReview(ctx, cmd, opts, regressionDetectorOptions{limit: limit, json: true, includeDeletions: inc, locationOnly: loc}, query)
473			}
474		case "brain_workspace_regressions":
475			workspace, stringErr := mcpOptionalString(params.Arguments, "workspace")
476			if stringErr != nil {
477				err = stringErr
478				break
479			}
480			workspace = strings.TrimSpace(workspace)
481			err = requireMCPQuery(query)
482			if err == nil && workspace == "" {
483				err = errors.New("workspace is required")
484			}
485			if err == nil {
486				inc, loc, boolErr := mcpRegressionBooleans(params.Arguments)
487				if boolErr != nil {
488					err = boolErr
489					break
490				}
491				err = runWorkspaceRegressions(cmd, opts, regressionDetectorOptions{limit: limit, json: true, includeDeletions: inc, locationOnly: loc}, workspace, query)
492			}
493		case "brain_workspace_review":
494			workspace, stringErr := mcpOptionalString(params.Arguments, "workspace")
495			if stringErr != nil {
496				err = stringErr
497				break
498			}
499			workspace = strings.TrimSpace(workspace)
500			err = requireMCPQuery(query)
501			if err == nil && workspace == "" {
502				err = errors.New("workspace is required")
503			}
504			if err == nil {
505				inc, loc, boolErr := mcpRegressionBooleans(params.Arguments)
506				if boolErr != nil {
507					err = boolErr
508					break
509				}
510				err = runWorkspaceReview(cmd, opts, regressionDetectorOptions{limit: limit, json: true, includeDeletions: inc, locationOnly: loc}, workspace, query)
511			}
512		default:
513			err = fmt.Errorf("unknown tool: %s", params.Name)
514		}
515		if err != nil {
516			return nil, err
517		}
518		return map[string]any{"content": []map[string]any{{"type": "text", "text": out.String()}}}, nil
519	}
520	
521	func requireMCPQuery(query string) error {
522		if strings.TrimSpace(query) == "" {
523			return errors.New("query is required")
524		}
525		return nil
526	}
527	
528	func validateMCPToolArguments(tool string, args map[string]any) error {
529		allowed := map[string]bool{}
530		add := func(keys ...string) {
531			for _, key := range keys {
532				allowed[key] = true
533			}
534		}
535		switch tool {
536		case "brain_stale":
537			add("blind_spots")
538		case "brain_brief":
539			add("task", "limit")
540		case "brain_query", "brain_search", "brain_vsearch":
541			add("query", "limit", "branch")
542		case "brain_context", "brain_code", "brain_tests":
543			add("query", "limit")
544		case "brain_get":
545			add("id", "branch")
546		case "brain_multi_get":
547			add("ids", "branch")
548		case "brain_impact":
549			add("query", "limit", "depth")
550		case "brain_changes":
551			add("limit")
552		case "brain_boundaries":
553			add("kind", "limit")
554		case "brain_regressions", "brain_review":
555			add("query", "limit", "include_deletions", "location_only")
556		case "brain_workspace_regressions", "brain_workspace_review":
557			add("workspace", "query", "limit", "include_deletions", "location_only")
558		default:
559			return nil
560		}
561		for key := range args {
562			if !allowed[key] {
563				return fmt.Errorf("unknown argument for %s: %s", tool, key)
564			}
565		}
566		return nil
567	}
568	
569	func mcpOptionalString(args map[string]any, key string) (string, error) {
570		value, ok := args[key]
571		if !ok || value == nil {
572			return "", nil
573		}
574		if typed, ok := value.(string); ok {
575			return typed, nil
576		}
577		return "", fmt.Errorf("%s must be string", key)
578	}
579	
580	func mcpBool(args map[string]any, key string) (bool, error) {
581		value, ok := args[key]
582		if !ok || value == nil {
583			return false, nil
584		}
585		boolValue, ok := value.(bool)
586		if !ok {
587			return false, fmt.Errorf("%s must be boolean", key)
588		}
589		return boolValue, nil
590	}
591	
592	func mcpRegressionBooleans(args map[string]any) (bool, bool, error) {
593		includeDeletions, err := mcpBool(args, "include_deletions")
594		if err != nil {
595			return false, false, err
596		}
597		locationOnly, err := mcpBool(args, "location_only")
598		if err != nil {
599			return false, false, err
600		}
601		return includeDeletions, locationOnly, nil
602	}
603	
604	func mcpStringSlice(args map[string]any, key string) ([]string, error) {
605		value, ok := args[key]
606		if !ok || value == nil {
607			return nil, nil
608		}
609		raw, ok := args[key].([]any)
610		if !ok {
611			return nil, fmt.Errorf("%s must be an array of strings", key)
612		}
613		out := make([]string, 0, len(raw))
614		for _, v := range raw {
615			s, ok := v.(string)
616			if !ok {
617				return nil, fmt.Errorf("%s must be an array of strings", key)
618			}
619			// Append the trimmed value so validation (non-empty) and downstream id
620			// resolution see the same string — " doc:abc " must resolve, not 404.
621			if trimmed := strings.TrimSpace(s); trimmed != "" {
622				out = append(out, trimmed)
623			}
624		}
625		return out, nil
626	}
627	
628	func mcpPositiveInt(args map[string]any, key string, fallback int) (int, error) {
629		value, ok := args[key]
630		if !ok {
631			return fallback, nil
632		}
633		switch typed := value.(type) {
634		case float64:
635			if typed >= 1 && typed <= float64(math.MaxInt) && math.Trunc(typed) == typed {
636				return int(typed), nil
637			}
638		case int:
639			if typed >= 1 {
640				return typed, nil
641			}
642		}
643		return 0, fmt.Errorf("%s must be an integer greater than zero", key)
644	}
645	
646	// errMCPRecoverable marks a single malformed/oversized frame that should be
647	// answered with a JSON-RPC parse error rather than terminating the session.
648	var errMCPRecoverable = errors.New("recoverable mcp frame error")
649	
650	// readBoundedLine reads one '\n'-terminated line while capping accumulated bytes
651	// at max, so a newline-less giant frame cannot exhaust memory during the read
652	// (ReadString would buffer it unbounded). On overflow it drains the remainder of
653	// the line (bounded) to keep the stream aligned and returns errMCPRecoverable.
654	func readBoundedLine(reader *bufio.Reader, max int) (string, error) {
655		var buf []byte
656		for {
657			chunk, err := reader.ReadSlice('\n')
658			if len(buf)+len(chunk) > max {
659				if err == bufio.ErrBufferFull {
660					drainMCPLine(reader)
661				}
662				return "", fmt.Errorf("%w: frame exceeds maximum size of %d bytes", errMCPRecoverable, max)
663			}
664			buf = append(buf, chunk...)
665			switch err {
666			case nil:
667				return string(buf), nil
668			case bufio.ErrBufferFull:
669				continue
670			default:
671				return string(buf), err
672			}
673		}
674	}
675	
676	// drainMCPLine discards the rest of an over-long line up to a bounded number of
677	// buffer-sized chunks, then gives up (a pathological newline-less stream stays
678	// memory-safe; only stream realignment is best-effort).
679	func drainMCPLine(reader *bufio.Reader) {
680		for i := 0; i < 64; i++ {
681			if _, err := reader.ReadSlice('\n'); err != bufio.ErrBufferFull {
682				return
683			}
684		}
685	}
686	
687	func readMCPMessage(reader *bufio.Reader) (mcpMessage, mcpFrameMode, error) {
688		length := -1
689		for {
690			line, err := readBoundedLine(reader, maxMCPFrameBytes)
691			if errors.Is(err, errMCPRecoverable) {
692				return mcpMessage{}, mcpFrameJSONLine, err
693			}
694			if err != nil {
695				return mcpMessage{}, "", err
696			}
697			line = strings.TrimRight(line, "\r\n")
698			if strings.HasPrefix(strings.TrimSpace(line), "{") {
699				trimmed := strings.TrimSpace(line)
700				// readBoundedLine already caps the line at maxMCPFrameBytes (an oversize
701				// NDJSON frame is reported there), so the only failure left here is a
702				// malformed line, which we make recoverable instead of fatal.
703				var msg mcpMessage
704				if err := json.Unmarshal([]byte(trimmed), &msg); err != nil {
705					return mcpMessage{}, mcpFrameJSONLine, fmt.Errorf("%w: %v", errMCPRecoverable, err)
706				}
707				return msg, mcpFrameJSONLine, nil
708			}
709			if line == "" {
710				break
711			}
712			name, value, ok := strings.Cut(line, ":")
713			if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
714				parsed, err := strconv.Atoi(strings.TrimSpace(value))
715				if err != nil {
716					return mcpMessage{}, "", err
717				}
718				if parsed < 0 {
719					return mcpMessage{}, "", errors.New("Content-Length must be non-negative")
720				}
721				length = parsed
722			}
723		}
724		if length < 0 {
725			return mcpMessage{}, "", errors.New("missing Content-Length")
726		}
727		if length > maxMCPFrameBytes {
728			return mcpMessage{}, "", fmt.Errorf("Content-Length exceeds maximum frame size of %d bytes", maxMCPFrameBytes)
729		}
730		data := make([]byte, length)
731		if _, err := io.ReadFull(reader, data); err != nil {
732			return mcpMessage{}, "", err
733		}
734		var msg mcpMessage
735		if err := json.Unmarshal(data, &msg); err != nil {
736			return mcpMessage{}, "", err
737		}
738		return msg, mcpFrameContentLength, nil
739	}
740	
741	func writeMCPMessage(out io.Writer, msg mcpMessage, frameMode mcpFrameMode) error {
742		data, err := json.Marshal(msg)
743		if err != nil {
744			return err
745		}
746		if frameMode == mcpFrameJSONLine {
747			_, err = fmt.Fprintf(out, "%s\n", data)
748			return err
749		}
750		_, err = fmt.Fprintf(out, "Content-Length: %d\r\n\r\n%s", len(data), data)
751		return err
752	}
